#!/usr/bin/env python3
"""
zunabo_brand.py - Charte graphique partagee Zunabo.

Source UNIQUE de verite pour l'apparence de tous les outils Zunabo.
Chaque outil importe ce module au lieu de redefinir son style.

Aligne sur les DOCUMENTS ADMINISTRATIFS Zunabo (flyers, carte, kit) :
  * Heros vert profond (#33492e) a grille fine, wordmark contoure, tagline Fredoka
  * Corps creme (#f6f2e9), titres verts, accents sauge (#7ba073) + or (#c19a3e)
  * Police Fredoka (arrondie) pour titres et wordmark
  * Tagline : "La technologie, en toute confiance."

Usage :
    import zunabo_brand as brand
    html = brand.document("Titre", inner_html)
    # classes : .z-card, .z-table, .badge.<sev>, .z-cve, .z-tag, .z-vuln.<sev>, .z-empty
    # severites : critical | high | medium | low | info
"""

import html as _html

PALETTE = {
    "green_deep": "#33492e",
    "green_dark": "#1b2617",
    "green_mid":  "#5f8257",
    "sage":       "#7ba073",
    "gold":       "#c19a3e",
    "paper":      "#f6f2e9",
    "card":       "#fffdf8",
    "ink":        "#20291b",
    "muted":      "#5c6a51",
    "line":       "#e2ddcf",
    "light":      "#cfe0c8",
    "critical":   "#b3282d",
    "high":       "#d9642a",
    "medium":     "#c19a3e",
    "low":        "#3f7d8c",
    "info":       "#8a9a80",
}

SEV_ORDER = ["critical", "high", "medium", "low", "info"]
TAGLINE = "La technologie, en toute confiance."

LOGO_B64 = ""

_FONTS = (
    '<link rel="preconnect" href="https://fonts.googleapis.com">'
    '<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>'
    '<link href="https://fonts.googleapis.com/css2?'
    'family=Fredoka:wght@400;500;600;700&display=swap" rel="stylesheet">'
)


def esc(x):
    return _html.escape(str(x))


def css():
    p = PALETTE
    return f""":root{{
  --green-deep:{p['green_deep']};--green-dark:{p['green_dark']};--green-mid:{p['green_mid']};
  --sage:{p['sage']};--gold:{p['gold']};--paper:{p['paper']};--card:{p['card']};
  --ink:{p['ink']};--muted:{p['muted']};--line:{p['line']};--light:{p['light']};
  --critical:{p['critical']};--high:{p['high']};--medium:{p['medium']};--low:{p['low']};--info:{p['info']};
}}
*{{box-sizing:border-box;}}
body{{margin:0;background:var(--paper);color:var(--ink);
  font:15px/1.55 -apple-system,BlinkMacSystemFont,Segoe UI,Roboto,Helvetica,Arial,sans-serif;}}
h1,h2,h3,.z-word,.z-tagline,.z-card .num,.badge,.z-kick{{
  font-family:"Fredoka",-apple-system,Segoe UI,sans-serif;}}
.z-wrap{{max-width:960px;margin:0 auto;background:var(--paper);box-shadow:0 0 60px rgba(0,0,0,.12);}}
.z-hero{{background:var(--green-deep);color:#fff;padding:34px 32px 26px;text-align:center;
  background-image:
    linear-gradient(rgba(255,255,255,.05) 1px,transparent 1px),
    linear-gradient(90deg,rgba(255,255,255,.05) 1px,transparent 1px);
  background-size:34px 34px;}}
.z-hero .logo{{height:56px;display:block;margin:0 auto 14px;}}
.z-tagline{{font-size:19px;font-weight:600;letter-spacing:.3px;}}
.z-tagline .accent{{color:var(--sage);}}
.z-divider{{width:120px;height:3px;background:var(--gold);border-radius:2px;margin:16px auto 0;}}
.z-body{{padding:26px 32px 40px;}}
h1{{font-size:23px;font-weight:600;color:var(--green-deep);margin:4px 0 12px;}}
.z-kick{{font-size:11px;letter-spacing:2.5px;text-transform:uppercase;color:var(--sage);font-weight:600;}}
h2{{font-size:15px;font-weight:600;color:var(--green-deep);margin:30px 0 12px;
  padding-bottom:7px;border-bottom:2px solid var(--gold);display:inline-block;}}
.z-meta{{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:7px 22px;
  font-size:13px;color:var(--muted);background:var(--card);border:1px solid var(--line);
  border-radius:12px;padding:16px 18px;}}
.z-meta b{{color:var(--green-deep);font-weight:600;}}
.z-cards{{display:grid;grid-template-columns:repeat(5,1fr);gap:10px;margin:22px 0;}}
.z-card{{background:var(--card);border:1px solid var(--line);border-radius:12px;padding:16px 8px;text-align:center;}}
.z-card .num{{font-size:30px;font-weight:600;color:var(--ink);}}
.z-card .lbl{{font-size:11px;color:var(--muted);margin-top:4px;letter-spacing:.5px;}}
.z-card.critical .num{{color:var(--critical);}} .z-card.high .num{{color:var(--high);}}
.z-card.medium .num{{color:var(--medium);}} .z-card.low .num{{color:var(--low);}}
.z-card.info .num{{color:var(--info);}}
.z-table{{width:100%;border-collapse:collapse;font-size:13px;background:var(--card);
  border:1px solid var(--line);border-radius:12px;overflow:hidden;}}
.z-table th,.z-table td{{text-align:left;padding:9px 12px;border-bottom:1px solid var(--line);vertical-align:top;}}
.z-table th{{background:var(--green-deep);color:var(--light);font-weight:600;font-size:11px;
  text-transform:uppercase;letter-spacing:.4px;}}
.z-table tr:last-child td{{border-bottom:none;}}
.z-table td{{color:var(--ink);}}
.z-vuln{{background:var(--card);border:1px solid var(--line);border-left-width:4px;
  border-radius:10px;padding:14px 16px;margin-bottom:12px;}}
.z-vuln.critical{{border-left-color:var(--critical);}} .z-vuln.high{{border-left-color:var(--high);}}
.z-vuln.medium{{border-left-color:var(--medium);}} .z-vuln.low{{border-left-color:var(--low);}}
.z-vuln.info{{border-left-color:var(--info);}}
.z-vhead{{display:flex;align-items:center;gap:10px;flex-wrap:wrap;}}
.badge{{font-size:11px;font-weight:600;padding:2px 10px;border-radius:20px;color:#fff;}}
.badge.critical{{background:var(--critical);}} .badge.high{{background:var(--high);}}
.badge.medium{{background:var(--medium);color:#3a2e10;}} .badge.low{{background:var(--low);}}
.badge.info{{background:var(--info);color:#20291b;}}
.z-vname{{font-weight:600;font-size:15px;color:var(--green-deep);}}
.z-cvss{{font-size:11px;color:var(--gold);border:1px solid var(--line);padding:1px 7px;border-radius:5px;}}
.z-conf{{font-size:10px;font-weight:600;letter-spacing:.5px;padding:1px 8px;border-radius:20px;text-transform:uppercase;}}
.z-conf.confirme{{background:var(--green-mid);color:#fff;}}
.z-conf.potentiel{{background:rgba(193,154,62,.18);color:var(--gold);border:1px solid var(--gold);}}
.z-evbox{{margin-top:9px;font-size:12px;}}
.z-evbox summary{{cursor:pointer;color:var(--sage);font-weight:600;user-select:none;}}
.z-evrow{{margin-top:5px;color:var(--muted);}}
.z-evrow b{{color:var(--green-deep);}}
.z-evich{{margin-top:6px;background:#f0ece0;border:1px solid var(--line);border-radius:6px;
  padding:8px 10px;font-family:ui-monospace,monospace;font-size:11px;color:var(--ink);
  white-space:pre-wrap;word-break:break-word;max-height:220px;overflow:auto;}}
.z-src{{margin-left:auto;font-size:11px;color:var(--muted);text-transform:uppercase;}}
.z-target{{color:var(--green-mid);font-family:ui-monospace,SFMono-Regular,Menlo,monospace;
  font-size:13px;margin:6px 0;word-break:break-all;}}
.z-desc{{color:var(--muted);font-size:13px;white-space:pre-wrap;margin-top:6px;}}
.z-cves,.z-tags{{margin-top:8px;}}
.z-cve{{display:inline-block;background:rgba(179,40,45,.09);color:var(--critical);
  font-family:ui-monospace,monospace;font-size:12px;padding:1px 7px;border-radius:5px;margin:2px 4px 2px 0;}}
.z-tag{{display:inline-block;background:rgba(123,160,115,.14);color:var(--green-mid);
  font-size:11px;padding:1px 7px;border-radius:5px;margin:2px 4px 2px 0;}}
.z-refs{{margin-top:8px;display:flex;flex-direction:column;gap:2px;}}
.z-refs a{{color:var(--low);font-size:12px;text-decoration:none;word-break:break-all;}}
.z-refs a:hover{{text-decoration:underline;}}
.z-empty{{color:var(--muted);text-align:center;padding:30px;}}
.z-foot{{background:var(--green-deep);color:var(--light);padding:16px 32px;
  display:flex;align-items:center;gap:12px;font-size:12px;}}
.z-foot .logo{{height:22px;}}
.z-foot .note{{margin-left:auto;text-align:right;color:var(--light);}}
@media(max-width:640px){{
  .z-cards{{grid-template-columns:repeat(2,1fr);}}
  .z-body,.z-hero,.z-foot{{padding-left:18px;padding-right:18px;}}
}}"""


def _logo_img(cls):
    return f'<img class="{cls}" alt="Zunabo" src="data:image/png;base64,{LOGO_B64}">'


def document(title, inner, footer_note="Les resultats automatises necessitent une validation manuelle"):
    """Enveloppe un contenu HTML dans la page de marque Zunabo (style doc admin)."""
    tagline = TAGLINE.replace("confiance.", '<span class="accent">confiance.</span>')
    return f"""<!DOCTYPE html><html lang="fr"><head><meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>{esc(title)} - Zunabo</title>
{_FONTS}
<style>{css()}</style></head><body><div class="z-wrap">
  <div class="z-hero">
    {_logo_img("logo")}
    <div class="z-tagline">{tagline}</div>
    <div class="z-divider"></div>
  </div>
  <div class="z-body">
  {inner}
  </div>
  <div class="z-foot">
    {_logo_img("logo")}
    <span class="note">{esc(footer_note)}</span>
  </div>
</div></body></html>"""
